<template>
  <section class="visitor-activity" data-activity-private aria-labelledby="visitor-activity-heading">
    <header class="activity-heading">
      <div><p class="activity-eyebrow">Private</p><h2 id="visitor-activity-heading">Visitor activity</h2></div>
      <div class="activity-filters">
        <label>Period<select v-model="days" @change="load"><option :value="7">7 days</option><option :value="30">30 days</option><option :value="90">90 days</option><option :value="365">365 days</option></select></label>
        <label>Traffic<select v-model="environment" @change="load"><option value="production">Live site</option><option value="test">Local tests</option></select></label>
        <button type="button" :disabled="loading" @click="load">{{ loading ? 'Loading…' : 'Refresh' }}</button>
        <button v-if="report" type="button" @click="download">Export report</button>
      </div>
    </header>
    <p class="activity-explanation">Anonymous browser visits, approximate network locations and time visible in the foreground. Background tabs and embedded demonstrations are excluded. A browser ID can change when storage is cleared and does not identify a person.</p>
    <p v-if="error" role="alert">{{ error }}</p>
    <template v-if="report">
      <dl class="activity-totals">
        <div><dt>Browsers</dt><dd>{{ number(report.summary.visitors) }}</dd></div>
        <div><dt>Sessions</dt><dd>{{ number(report.summary.sessions) }}</dd></div>
        <div><dt>Places visited</dt><dd>{{ number(report.summary.stops) }}</dd></div>
        <div><dt>Foreground time</dt><dd>{{ duration(report.summary.visible_ms) }}</dd></div>
      </dl>
      <div class="activity-overview">
        <section><h3>Countries and regions</h3><ul><li v-for="row in report.countries" :key="row.country"><span>{{ countryName(row.country) }}</span><span>{{ row.sessions }} sessions</span></li></ul><p v-if="!report.countries.length">New visits will appear here.</p></section>
        <section><h3>Pages and Views</h3><ul><li v-for="row in report.pages" :key="row.path + row.presentation"><span>{{ row.path }} <small>{{ row.presentation }}</small></span><span>{{ row.sessions }} sessions <small>{{ duration(row.visible_ms) }}</small></span></li></ul></section>
      </div>
      <h3>Recent sessions</h3>
      <p class="activity-explanation">The latest 100 sessions in this period. Open a session to see each place visited, then open a place to see its interactions. Time at a place includes reading and looking around while the tab is visible.</p>
      <ol class="activity-sessions">
        <li v-for="session in report.sessions" :key="session.session_id">
          <button class="activity-session" type="button" :aria-expanded="selected === session.session_id" @click="openSession(session)">
            <span><strong>Visitor {{ session.visitor_id.slice(0, 8) }}</strong><small>{{ countryName(session.country) }} · {{ session.device }} · {{ date(session.started_at) }}</small></span>
            <span>{{ duration(session.visible_ms) }}<small>{{ session.stops }} places · {{ session.referrer || 'No referring site supplied' }}</small></span>
            <svg viewBox="0 0 16 16" aria-hidden="true" :class="{ expanded: selected === session.session_id }"><path d="m4 6 4 4 4-4"/></svg>
          </button>
          <div v-if="selected === session.session_id" class="activity-timeline">
            <p v-if="timelineBusy" role="status">Loading visit…</p><p v-if="timelineError" role="alert">{{ timelineError }}</p>
            <ol><li v-for="visit in visits" :key="visit.id">
              <button type="button" class="activity-stop" :aria-expanded="!!actions[visit.id]" @click="openVisit(visit)">
                <span><time>{{ time(visit.started_at) }}</time><strong>{{ visit.title || visit.path }}</strong><small>{{ visit.presentation }} · {{ visit.place || 'Page opened' }}</small></span><span>{{ duration(visit.visible_ms) }}</span>
              </button>
              <div v-if="actions[visit.id]" class="activity-events">
                <p v-if="actions[visit.id].busy">Loading interactions…</p><p v-if="actions[visit.id].error" role="alert">{{ actions[visit.id].error }}</p>
                <ol><li v-for="event in actions[visit.id].events" :key="event.id"><time>{{ time(event.occurred_at) }}</time><span>{{ event.action.replaceAll('_', ' ') }} <strong>{{ event.target }}</strong><small v-if="event.detail">{{ event.detail }}</small></span></li></ol>
                <p v-if="!actions[visit.id].busy && !actions[visit.id].events.length">No control interactions recorded at this stop.</p>
                <button v-if="actions[visit.id].next !== null" type="button" @click="loadActions(visit, true)">More interactions</button>
              </div>
            </li></ol>
            <button v-if="nextVisit !== null" type="button" :disabled="timelineBusy" @click="loadSession(true)">Earlier places</button>
          </div>
        </li>
      </ol>
      <p v-if="!report.sessions.length">No visits recorded in this period.</p>
    </template>
    <section class="activity-notes"><h3>Guestbook notes</h3><p class="activity-explanation">The notes are public in their exhibitions. Their visitor details below are private.</p>
      <ol><li v-for="note in notes" :key="note.id"><router-link :to="`/view/${note.share_id}`">{{ note.title }}</router-link><p>{{ note.text }}</p><small>{{ date(note.created_at) }} · {{ visitorContextLabel(note.visitor_context_json) }}</small></li></ol>
      <p v-if="notesError" role="alert">{{ notesError }}</p><p v-else-if="!notes.length && !notesBusy">No guestbook notes yet.</p>
      <button type="button" :disabled="notesBusy" @click="loadNotes(nextNote !== null)">{{ notesBusy ? 'Loading…' : nextNote !== null ? 'More notes' : 'Refresh notes' }}</button>
    </section>
  </section>
</template>

<script>
import { listVisitorActivity, listVisitorNotes } from '../../utils/viewShareSite';
import { countryName, visitorContextLabel } from '../../utils/visitorContextLabel';
export default {
  data: () => ({ days: 30, environment: 'production', report: null, loading: false, error: '', selected: '', visits: [], nextVisit: null, timelineBusy: false, timelineError: '', actions: {}, notes: [], nextNote: null, notesBusy: false, notesError: '' }),
  mounted() { this.load(); this.loadNotes(); },
  beforeUnmount() { this._closed = true; this._request = (this._request || 0) + 1; },
  methods: {
    countryName, visitorContextLabel,
    number(value) { return Number(value || 0).toLocaleString('en'); },
    duration(ms) { const seconds = Math.round((ms || 0) / 1000); return seconds < 60 ? `${seconds}s` : seconds < 3600 ? `${Math.floor(seconds / 60)}m ${seconds % 60}s` : `${Math.floor(seconds / 3600)}h ${Math.floor(seconds % 3600 / 60)}m`; },
    date(value) { return new Date(value).toLocaleString('en', { dateStyle: 'medium', timeStyle: 'short' }); },
    time(value) { return new Date(value).toLocaleTimeString('en', { hour12: false }); },
    async load() {
      const request = this._request = (this._request || 0) + 1;
      this.loading = true; this.error = ''; this.selected = ''; this.visits = []; this.actions = {}; this.report = null;
      try { const report = await listVisitorActivity({ days: this.days, environment: this.environment }); if (!this._closed && request === this._request) this.report = report; }
      catch { if (request === this._request) this.error = 'Visit records are temporarily unavailable. Try refreshing or sign in again.'; }
      finally { if (request === this._request) this.loading = false; }
    },
    openSession(session) { this.selected = this.selected === session.session_id ? '' : session.session_id; this.visits = []; this.actions = {}; this.nextVisit = null; if (this.selected) this.loadSession(); },
    async loadSession(more = false) {
      const selected = this.selected, environment = this.environment;
      this.timelineBusy = true; this.timelineError = '';
      try {
        const result = await listVisitorActivity({ session: selected, environment, ...(more ? { before: this.nextVisit } : {}) });
        if (this._closed || selected !== this.selected || environment !== this.environment) return;
        this.visits = [...(more ? this.visits : []), ...result.visits].sort((a, b) => a.started_at - b.started_at); this.nextVisit = result.next;
      } catch { if (selected === this.selected) this.timelineError = 'This visit could not be loaded. Open the session again to retry.'; }
      finally { if (selected === this.selected) this.timelineBusy = false; }
    },
    openVisit(visit) { if (this.actions[visit.id]) delete this.actions[visit.id]; else this.loadActions(visit); },
    async loadActions(visit, more = false) {
      let row = more ? this.actions[visit.id] : { events: [], busy: false, error: '', next: null };
      this.actions[visit.id] = row; row = this.actions[visit.id]; row.busy = true; row.error = '';
      try { const result = await listVisitorActivity({ visit: visit.id, environment: this.environment, offset: more ? row.next : 0 }); row.events.push(...result.events); row.next = result.next; }
      catch { row.error = 'Interactions could not be loaded. Close and reopen this stop to retry.'; }
      finally { row.busy = false; }
    },
    async loadNotes(more = false) {
      this.notesBusy = true; this.notesError = '';
      try { const result = await listVisitorNotes(more ? this.nextNote : 0); if (!this._closed) { this.notes = [...(more ? this.notes : []), ...result.notes]; this.nextNote = result.next_offset; } }
      catch { this.notesError = 'Guestbook notes are temporarily unavailable.'; }
      finally { this.notesBusy = false; }
    },
    download() {
      const blob = new Blob([JSON.stringify({ exported_at: new Date().toISOString(), ...this.report, opened_session: this.selected || null, opened_session_visits: this.visits, opened_interactions: this.actions }, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob), anchor = document.createElement('a'); anchor.href = url; anchor.download = `visitor-report-${new Date().toISOString().slice(0, 10)}.json`; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
    },
  },
};
</script>

<style scoped>
.visitor-activity{margin:4rem 0;color:var(--text-color);font-family:inherit}.activity-heading{display:flex;justify-content:space-between;align-items:end;gap:1.5rem;flex-wrap:wrap}.activity-eyebrow{font-size:.7rem;text-transform:uppercase;letter-spacing:.14em;opacity:.6;margin:0 0 .5rem}.activity-heading h2{margin:0;font-size:1.7rem}.activity-filters{display:flex;align-items:end;gap:.8rem;flex-wrap:wrap}.activity-filters label{display:grid;gap:.3rem;font-size:.7rem}.visitor-activity button,.visitor-activity select{font:inherit;color:inherit;background:transparent;border:1px solid color-mix(in srgb,currentColor 18%,transparent);padding:.5rem .65rem;border-radius:3px}.visitor-activity button{cursor:pointer}.visitor-activity button:hover{background:color-mix(in srgb,currentColor 5%,transparent)}.activity-explanation{max-width:76ch;font-size:.85rem;line-height:1.6;opacity:.7}.activity-totals{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem;margin:2rem 0}.activity-totals>div{padding:1rem;background:color-mix(in srgb,currentColor 4%,transparent)}dt{font-size:.75rem;opacity:.65}dd{margin:.35rem 0 0;font-size:1.75rem;font-variant-numeric:tabular-nums}.activity-overview{display:grid;grid-template-columns:1fr 1.5fr;gap:2rem}h3{font-size:1rem;margin:1.6rem 0 .8rem}.visitor-activity ol,.visitor-activity ul{list-style:none;margin:0;padding:0}.activity-overview li{display:flex;justify-content:space-between;gap:1rem;padding:.6rem 0;border-bottom:1px solid color-mix(in srgb,currentColor 12%,transparent);font-size:.85rem;overflow-wrap:anywhere}.visitor-activity small{display:block;font-size:.73rem;line-height:1.5;opacity:.6;font-weight:400}.activity-sessions>li{border-top:1px solid color-mix(in srgb,currentColor 15%,transparent)}.activity-session,.activity-stop{display:flex;justify-content:space-between;align-items:center;gap:1rem;width:100%;text-align:left!important;border:0!important;padding:1rem .6rem!important}.activity-session strong,.activity-stop strong{font-weight:500}.activity-session>span:nth-child(2){margin-left:auto;text-align:right}.activity-session svg{width:16px;height:16px;fill:none;stroke:currentColor;flex-shrink:0}.activity-session svg.expanded{transform:rotate(180deg)}.activity-timeline{padding:.5rem 1rem 1.2rem;background:color-mix(in srgb,currentColor 3%,transparent)}.activity-stop{font-size:.85rem!important}.activity-stop time{font-size:.7rem;opacity:.6;margin-right:.7rem;font-variant-numeric:tabular-nums}.activity-events{padding:.3rem 1rem 1rem;font-size:.8rem}.activity-events li{display:flex;gap:.8rem;padding:.4rem 0;overflow-wrap:anywhere}.activity-events time{flex-shrink:0;font-variant-numeric:tabular-nums;opacity:.55}.activity-events strong{font-weight:500}.activity-notes{margin-top:3rem}.activity-notes li{padding:1rem 0}.activity-notes p{white-space:pre-wrap}.activity-notes small{overflow-wrap:anywhere}@media(max-width:700px){.activity-totals{grid-template-columns:repeat(2,1fr)}.activity-overview{grid-template-columns:1fr;gap:0}.activity-session{flex-wrap:wrap}.activity-session>span:nth-child(2){text-align:left;margin-left:0}.activity-session svg{margin-left:auto}.activity-timeline{padding:.25rem .25rem 1rem}.activity-stop time{display:block}.activity-stop strong{overflow-wrap:anywhere}.activity-filters{font-size:.85rem}}
</style>
